CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','staff')),active INTEGER NOT NULL DEFAULT 1);
 CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),school TEXT NOT NULL,head TEXT NOT NULL DEFAULT '',director TEXT NOT NULL DEFAULT '',officer TEXT NOT NULL DEFAULT '');
 INSERT INTO settings(id,school) VALUES(1,'โรงเรียนกาวิละวิทยาลัย') ON CONFLICT(id) DO NOTHING;
 CREATE TABLE IF NOT EXISTS counters(kind TEXT,year INTEGER,value INTEGER NOT NULL,PRIMARY KEY(kind,year));
 CREATE TABLE IF NOT EXISTS records(id INTEGER PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('purchase','hire')),year INTEGER NOT NULL,number INTEGER NOT NULL,title TEXT NOT NULL,date TEXT NOT NULL,reason TEXT NOT NULL,vendor TEXT NOT NULL,vendorAddress TEXT NOT NULL,items TEXT NOT NULL,total INTEGER NOT NULL CHECK(total>0 AND total<=500000),budget TEXT NOT NULL,method TEXT NOT NULL,school TEXT NOT NULL,head TEXT NOT NULL,director TEXT NOT NULL,officer TEXT NOT NULL,createdBy INTEGER REFERENCES users(id),createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(kind,year,number));
 CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,userId INTEGER REFERENCES users(id),action TEXT NOT NULL,recordId INTEGER,detail TEXT NOT NULL,createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS sessions(sid TEXT PRIMARY KEY,data TEXT NOT NULL,expires INTEGER NOT NULL);